using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "ResetRunesApplyEffectCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Moonie/ResetRunesApplyEffectCustomDescription", order = 0)]
public class ResetRunesApplyEffectCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		ResetRunesApplyEffectAction obj = battleAction as ResetRunesApplyEffectAction;
		string actionDescription = obj.EffectAction.GetActionDescription(GetFinalAmountWithoutEquation(amountModified));
		string actionDescription2 = obj.RefreshAction.GetActionDescription(EffectsValues.NO_VALUE);
		return actionDescription + "\n" + actionDescription2;
	}
}
